<?php require_once 'config/auth.php'; require_admin(); $pageTitle='Historial de movimientos';
$producto=(int)($_GET['producto']??0);$tipo=$_GET['tipo']??'';$desde=$_GET['desde']??'';$hasta=$_GET['hasta']??'';$where=[];$params=[];
if($producto){$where[]='m.id_producto=?';$params[]=$producto;}if(in_array($tipo,['entrada','salida'],true)){$where[]='m.tipo=?';$params[]=$tipo;}if($desde){$where[]='m.fecha>=?';$params[]=$desde.' 00:00:00';}if($hasta){$where[]='m.fecha<=?';$params[]=$hasta.' 23:59:59';}$sql='SELECT m.*,p.codigo,p.nombre producto,u.nombre usuario FROM movimiento m JOIN producto p ON p.id_producto=m.id_producto JOIN usuario u ON u.id_usuario=m.id_usuario'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY m.fecha DESC';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$products=$pdo->query('SELECT id_producto,nombre FROM producto ORDER BY nombre')->fetchAll();require 'partials/header.php'; ?>
<div class="page-head"><div><span class="eyebrow">TRAZABILIDAD</span><h1>Historial de movimientos</h1><p>Consulta entradas y salidas por producto, tipo y fecha.</p></div></div><form class="filter" method="get"><select name="producto"><option value="0">Todos los productos</option><?php foreach($products as $p):?><option value="<?=$p['id_producto']?>" <?=$producto===$p['id_producto']?'selected':''?>><?=e($p['nombre'])?></option><?php endforeach;?></select><select name="tipo"><option value="">Todos los tipos</option><option value="entrada" <?=$tipo==='entrada'?'selected':''?>>Entradas</option><option value="salida" <?=$tipo==='salida'?'selected':''?>>Salidas</option></select><input type="date" name="desde" value="<?=e($desde)?>"><input type="date" name="hasta" value="<?=e($hasta)?>"><button class="btn primary">Filtrar</button><a class="btn ghost" href="historial.php">Limpiar</a></form><div class="panel"><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Usuario</th><th>Observación</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('d/m/Y H:i',strtotime($r['fecha'])))?></td><td><b><?=e($r['producto'])?></b><small><?=e($r['codigo'])?></small></td><td><span class="badge <?=$r['tipo']==='entrada'?'success':'info'?>"><?=e(ucfirst($r['tipo']))?></span></td><td><?=e((string)$r['cantidad'])?></td><td><?=e($r['usuario'])?></td><td><?=e($r['observacion']??'')?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty">No hay movimientos con esos filtros.</div><?php endif;?></div><?php require 'partials/footer.php'; ?>
